<?php
require_once dirname(__DIR__) . '/_common.php';$pageTitle='Galeri & album';$items=$pdo->query("SELECT a.*, (SELECT judul FROM kegiatan WHERE id=a.kegiatan_id) AS kegiatan_judul, (SELECT COUNT(*) FROM galeri_foto f WHERE f.album_id=a.id) AS foto_count, (SELECT file FROM galeri_foto WHERE album_id=a.id ORDER BY id ASC LIMIT 1) AS cover FROM galeri_album a ORDER BY a.tanggal DESC,a.id DESC")->fetchAll();osis_admin_page_start($pageTitle);
?>
<div class="admin-page-actions"><p>Buat album, unggah beberapa foto sekaligus, dan hubungkan dokumentasi ke kegiatan.</p><a class="button button-primary" href="<?=osis_e(osis_url('admin/galeri/album-tambah.php'))?>">＋ Buat album</a></div><div class="admin-album-grid"><?php if($items):foreach($items as $i=>$item):?><article class="admin-album-card"><a href="<?=osis_e(osis_url('public/galeri-album.php?id='.(int)$item['id']))?>" target="_blank" rel="noopener" class="admin-album-cover"><?php if($item['cover']):?><img src="<?=osis_e(osis_image_url($item['cover']))?>" alt=""><?php else:?><span>▧</span><?php endif;?><b><?=(int)$item['foto_count']?> foto</b></a><div class="admin-album-info"><span class="mini-date"><?=osis_e(osis_format_date($item['tanggal']))?></span><h2><?=osis_e($item['judul'])?></h2><p><?=osis_e(mb_strimwidth(strip_tags((string)$item['deskripsi']),0,105,'…','UTF-8'))?></p><?php if($item['kegiatan_judul']):?><small class="album-linked-event">↳ <?=osis_e($item['kegiatan_judul'])?></small><?php endif;?><div class="table-actions album-actions"><a class="table-action" href="<?=osis_e(osis_url('admin/galeri/foto-upload.php?id='.(int)$item['id']))?>">+ Foto</a><a class="table-action" href="<?=osis_e(osis_url('admin/galeri/album-edit.php?id='.(int)$item['id']))?>">Edit album</a><form method="post" action="<?=osis_e(osis_url('admin/galeri/album-hapus.php'))?>" data-confirm="Hapus album dan seluruh foto di dalamnya? Aksi ini tidak dapat dibatalkan."><?=osis_csrf_input()?><input type="hidden" name="id" value="<?=(int)$item['id']?>"><button class="table-action danger-text" type="submit">Hapus</button></form></div></div></article><?php endforeach;else:?><div class="empty-state admin-empty"><span>▧</span><h3>Belum ada album foto</h3><p>Buat album pertama untuk menambahkan dokumentasi kegiatan.</p><a class="button button-primary" href="<?=osis_e(osis_url('admin/galeri/album-tambah.php'))?>">Buat album <span>↗</span></a></div><?php endif;?></div>
<?php osis_admin_page_end(); ?>
